FUNCTION UNDER TEST:
Name: kMeans
Signature: cluster* kMeans(observation observations[], size_t size, int k)
Description: /**
 * @brief Perform k-means clustering on a set of 2D observations.
 *
 * Partitions the given observations into k clusters using the k-means algorithm,
 * updating each observation's group assignment in-place. Handles edge cases where
 * k is 1 (all points in one cluster) or k >= size (each point is its own cluster).
 *
 * @param observations Array of 2D data points to cluster. Must not be NULL and must have at least one element.
 *                     The group field of each observation is modified to indicate its assigned cluster.
 * @param size Number of observations in the array. Must be positive.
 * @param k Number of clusters to form. Must be at least 1.
 *
 * @return Pointer to an array of k cluster centroids on success, or NULL on allocation failure.
 *
 * @note Memory: Caller must free the returned cluster array.
 * @note The observations array is modified in-place to reflect cluster assignments.
 */
Dependencies: calculateCentroid, calculateNearst

FUNCTION IMPLEMENTATION (REFERENCE ONLY - do NOT copy into test):
```c
// C program for the function called kMeans
// Contains target function implementation and dependency signatures

#include <float.h>        /* DBL_MAX, DBL_MIN */
#include <math.h>         /* PI, sin, cos */
#include <stdio.h>        /* printf */
#include <stdlib.h>       /* rand */
#include <string.h>       /* memset */
#include <time.h>         /* time */

struct cluster
{
    double x;     /**< abscissa centroid of this cluster */
    double y;     /**< ordinate of centroid of this cluster */
    size_t count; /**< count of observations present in this cluster */
};

struct observation
{
    double x;  /**< abscissa of 2D data point */
    double y;  /**< ordinate of 2D data point */
    int group; /**< the group no in which this observation would go */
};

// Forward declarations for dependency functions
void calculateCentroid(observation observations[], size_t size,
                       cluster* centroid);
int calculateNearst(observation* o, cluster clusters[], int k);

// Target function implementation
cluster* kMeans(observation observations[], size_t size, int k)
{
    cluster* clusters = NULL;
    if (k <= 1)
    {
        /*
        If we have to cluster them only in one group
        then calculate centroid of observations and
        that will be a ingle cluster
        */
        clusters = (cluster*)malloc(sizeof(cluster));
        memset(clusters, 0, sizeof(cluster));
        calculateCentroid(observations, size, clusters);
    }
    else if (k < size)
    {
        clusters = malloc(sizeof(cluster) * k);
        memset(clusters, 0, k * sizeof(cluster));
        /* STEP 1 */
        for (size_t j = 0; j < size; j++)
        {
            observations[j].group = rand() % k;
        }
        size_t changed = 0;
        size_t minAcceptedError =
            size /
            10000;  // Do until 99.99 percent points are in correct cluster
        int t = 0;
        do
        {
            /* Initialize clusters */
            for (int i = 0; i < k; i++)
            {
                clusters[i].x = 0;
                clusters[i].y = 0;
                clusters[i].count = 0;
            }
            /* STEP 2*/
            for (size_t j = 0; j < size; j++)
            {
                t = observations[j].group;
                clusters[t].x += observations[j].x;
                clusters[t].y += observations[j].y;
                clusters[t].count++;
            }
            for (int i = 0; i < k; i++)
            {
                clusters[i].x /= clusters[i].count;
                clusters[i].y /= clusters[i].count;
            }
            /* STEP 3 and 4 */
            changed = 0;  // this variable stores change in clustering
            for (size_t j = 0; j < size; j++)
            {
                t = calculateNearst(observations + j, clusters, k);
                if (t != observations[j].group)
                {
                    changed++;
                    observations[j].group = t;
                }
            }
        } while (changed > minAcceptedError);  // Keep on grouping until we have
                                               // got almost best clustering
    }
    else
    {
        /* If no of clusters is more than observations
           each observation can be its own cluster
        */
        clusters = (cluster*)malloc(sizeof(cluster) * k);
        memset(clusters, 0, k * sizeof(cluster));
        for (int j = 0; j < size; j++)
        {
            clusters[j].x = observations[j].x;
            clusters[j].y = observations[j].y;
            clusters[j].count = 1;
            observations[j].group = j;
        }
    }
    return clusters;
}

```

