#include "unity.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_kMeans_k_equals_1_single_cluster(void) {
    // Setup: 3 points in a triangle
    observation observations[3];
    observations[0].x = 0.0; observations[0].y = 0.0; observations[0].group = -1;
    observations[1].x = 2.0; observations[1].y = 0.0; observations[1].group = -1;
    observations[2].x = 1.0; observations[2].y = 2.0; observations[2].group = -1;
    size_t size = 3;
    int k = 1;

    // Expected centroid: mean of all points
    double expected_x[1] = { (0.0 + 2.0 + 1.0) / 3.0 };
    double expected_y[1] = { (0.0 + 0.0 + 2.0) / 3.0 };
    int expected_groups[3] = { 0, 0, 0 };

    // Test: call kMeans
    cluster* clusters = kMeans(observations, size, k);

    // Assertions
    TEST_ASSERT_NOT_NULL(clusters);
    TEST_ASSERT_EQUAL_INT(1, k);
    TEST_ASSERT_EQUAL_SIZE_T(3, clusters[0].count);

    // All observations should be assigned to group 0
    for (size_t i = 0; i < size; ++i) {
        TEST_ASSERT_EQUAL_INT(0, observations[i].group);
    }

    // Centroid should match expected (within epsilon)
    double epsilon = 1e-8;
    TEST_ASSERT_FLOAT_WITHIN(epsilon, expected_x[0], clusters[0].x);
    TEST_ASSERT_FLOAT_WITHIN(epsilon, expected_y[0], clusters[0].y);

    // Cleanup
    helper_free_clusters(clusters);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_kMeans_k_equals_1_single_cluster);
    return UNITY_END();
}
